# frozen_string_literal: true

require "rails/generators"
require "rails/generators/active_record"
require "ripper"

module RailsNewadmin
  module Generators
    class InstallGenerator < Rails::Generators::Base
      include Rails::Generators::Migration
      source_root Engine.root.join("db/migrate")
      class_option :authentication, type: :string, default: "builtin"
      class_option :path, type: :string, default: "/admin"

      INITIALIZER_PATH = "config/initializers/rails_newadmin.rb"
      INITIALIZER_CONTENT = <<~RUBY
        # Generated by rails-newadmin:install. Edited files are preserved by destroy.
        RailsNewadmin.configure do |config|
          config.site_title = "NewAdmin"
          config.default_locale = :es
          config.default_mode = :auto
          # Production requires a shared atomic cache for rate limiting.
          # config.rate_limit_store = Rails.cache
        end
      RUBY

      def self.next_migration_number(directory)
        ActiveRecord::Generators::Base.next_migration_number(directory)
      end

      def validate_destination
        raise Thor::Error, "Only builtin authentication is available in this alpha" unless options[:authentication] == "builtin"
        raise Thor::Error, "path must be an absolute path with simple segments" unless %r{\A/(?:[a-z][a-z0-9_-]*)(?:/[a-z][a-z0-9_-]*)*\z}.match?(options[:path])
        routes = File.join(destination_root, "config/routes.rb")
        raise Thor::Error, "Run this inside a full Rails application" unless File.file?(routes)
        @routes = File.read(routes)
        @routing_source = routing_source(@routes)
        return if behavior == :revoke || existing_mount?
        path_pattern = /["']\/?#{Regexp.escape(options[:path].delete_prefix("/"))}(?:\/|\(|["'])/
        raise Thor::Error, "Mount path already appears in routes; choose --path" if @routing_source.match?(path_pattern)
        first_segment = Regexp.escape(options[:path].split("/").fetch(1))
        prefix_pattern = /\b(?:namespace|scope|get|post|put|patch|delete|match|resources?)\s*\(?\s*:#{first_segment}\b/
        raise Thor::Error, "Mount path overlaps existing routes; choose --path" if @routing_source.match?(prefix_pattern)
        alias_pattern = /(?:\bas:|:as\s*=>)\s*(?::rails_newadmin\b|["']rails_newadmin["'])/
        raise Thor::Error, "Route helper rails_newadmin is already in use" if @routing_source.match?(alias_pattern)
      end

      def install_configuration
        absolute = File.join(destination_root, INITIALIZER_PATH)
        if behavior == :revoke
          return unless File.exist?(absolute) || File.symlink?(absolute)
          if File.file?(absolute) && !File.symlink?(absolute) && File.binread(absolute) == INITIALIZER_CONTENT
            create_file INITIALIZER_PATH, INITIALIZER_CONTENT
          else
            say_status :preserve, "#{INITIALIZER_PATH} (edited or pre-existing; review manually)"
          end
        elsif File.exist?(absolute) || File.symlink?(absolute)
          say_status :preserve, INITIALIZER_PATH
        else
          create_file INITIALIZER_PATH, INITIALIZER_CONTENT
        end
      end

      def install_mount
        if behavior == :revoke
          active_lines = mount_lines(@routing_source)
          @routes.lines.each_with_index do |line, index|
            next unless active_lines.include?(index + 1)
            original_path = line[/ # rails-newadmin:install (\/[a-z0-9_\/-]+)\n\z/, 1]
            next unless original_path && line == "  #{mount_code(original_path)}\n"
            gsub_file "config/routes.rb", /^#{Regexp.escape(line)}/, "", force: true
          end
          say_status :preserve, "Review any edited or pre-existing RailsNewadmin::Engine mount manually" if existing_mount?(routing_source(File.read(File.join(destination_root, "config/routes.rb"))))
        elsif !existing_mount?
          route mount_code(options[:path])
        end
      end

      def install_migrations
        if behavior == :revoke
          say_status :preserve, "Database migrations and all database data"
          return
        end
        Dir[Engine.root.join("db/migrate/*.rb")].sort.each do |source|
          name = File.basename(source).sub(/\A\d+_/, "")
          next if Dir[File.join(destination_root, "db/migrate/*_#{name}")].any?
          migration_template File.basename(source), "db/migrate/#{name}"
        end
      end

      def instructions
        if behavior == :revoke
          say "Review preserved files manually. Database migrations and data have not been removed."
        else
          say "Next: bin/rails db:migrate; register resources; bin/rails rails_newadmin:permissions:sync; bin/rails rails_newadmin:admin:create"
        end
      end

      private

      def routing_source(contents)
        # Preserve newlines so a commented example cannot hide the next statement.
        comments = %i[on_comment on_embdoc_beg on_embdoc on_embdoc_end]
        Ripper.lex(contents).map { |_, type, text, _| comments.include?(type) ? text.gsub(/[^\r\n]/, "") : text }.join
      end

      def existing_mount?(source = @routing_source)
        mount_lines(source).any?
      end

      def mount_lines(source)
        lines = source.lines
        Ripper.lex(source).filter_map do |(line, column), type, text, _|
          next unless type == :on_ident && text == "mount"
          suffix = lines.drop(line - 1).join.byteslice(column..)
          line if suffix.match?(/\Amount\s*(?:\(\s*)?RailsNewadmin::Engine\b/)
        end
      end

      def mount_code(path)
        "mount RailsNewadmin::Engine => #{path.inspect}, as: :rails_newadmin # rails-newadmin:install #{path}"
      end
    end
  end
end
